    <style>
        /* ===========================================
           CSS CUSTOM PROPERTIES (THEME)
           Dark analytical theme for ML researchers
           =========================================== */
        :root {
            /* Colors — Deep navy + cyan/magenta accents */
            --bg-primary: #0a0f1c;
            --bg-secondary: #111827;
            --bg-card: #1a2332;
            --text-primary: #ffffff;
            --text-secondary: #9ca3af;
            --accent: #00ffcc;
            --accent-secondary: #ff00aa;
            --accent-glow: rgba(0, 255, 204, 0.3);

            /* Lab colors */
            --openai: #10a37f;
            --google: #4285f4;
            --anthropic: #d4a574;
            --muse: #a855f7;
            --meta: #0668e1;

            /* Typography — MUST use clamp() */
            --font-display: 'Clash Display', sans-serif;
            --font-body: 'Satoshi', sans-serif;
            --title-size: clamp(1.8rem, 5vw, 3.5rem);
            --h2-size: clamp(1.3rem, 3.5vw, 2.2rem);
            --h3-size: clamp(1rem, 2vw, 1.4rem);
            --body-size: clamp(0.7rem, 1.3vw, 1rem);
            --small-size: clamp(0.6rem, 1vw, 0.8rem);

            /* Spacing — MUST use clamp() */
            --slide-padding: clamp(1.5rem, 4vw, 4rem);
            --content-gap: clamp(0.8rem, 2vw, 1.5rem);
            --element-gap: clamp(0.3rem, 1vw, 0.8rem);

            /* Animation */
            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
            --duration-normal: 0.6s;
        }

        /* ===========================================
           BASE STYLES
           =========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }

        html, body {
            height: 100%;
            overflow-x: hidden;
        }

        html {
            scroll-snap-type: y mandatory;
            scroll-behavior: smooth;
        }

        body {
            font-family: var(--font-body);
            background: var(--bg-primary);
            color: var(--text-primary);
            line-height: 1.5;
        }

        /* ===========================================
           VIEWPORT FITTING: MANDATORY BASE STYLES
           =========================================== */
        .slide {
            width: 100vw;
            height: 100vh;
            height: 100dvh;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            position: relative;
        }

        .slide-content {
