        .domain-frontier h3 { color: var(--accent); }

        .domain-safety { border-left: 3px solid var(--anthropic); }
        .domain-safety h3 { color: var(--anthropic); }

        .domain-multimodal { border-left: 3px solid var(--google); }
        .domain-multimodal h3 { color: var(--google); }

        /* ===========================================
           DATA TABLES
           =========================================== */
        .data-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: var(--content-gap);
            font-size: var(--small-size);
        }

        .data-table th {
            text-align: left;
            padding: clamp(0.4rem, 1vw, 0.8rem);
            border-bottom: 2px solid var(--accent);
            color: var(--accent);
            font-weight: 600;
        }

        .data-table td {
            padding: clamp(0.3rem, 0.8vw, 0.6rem);
            border-bottom: 1px solid rgba(255, 255, 255, 0.1);
        }

        .data-table tr:hover td {
            background: rgba(0, 255, 204, 0.05);
        }

        .score {
            font-weight: 700;
            color: var(--text-primary);
        }

        .lab-openai { color: var(--openai); }
        .lab-google { color: var(--google); }
        .lab-anthropic { color: var(--anthropic); }
        .lab-muse { color: var(--muse); }

        /* ===========================================
           BAR CHART
           =========================================== */
        .bar-chart {
            display: flex;
            flex-direction: column;
            gap: var(--element-gap);
            margin-top: var(--content-gap);
        }

        .bar-row {
            display: flex;
            align-items: center;
            gap: var(--element-gap);
        }

        .bar-label {
            width: clamp(80px, 15vw, 180px);
            font-size: var(--small-size);
            text-align: right;
            flex-shrink: 0;
        }

        .bar-container {
            flex: 1;
            height: clamp(16px, 2.5vw, 28px);
            background: var(--bg-card);
            border-radius: 4px;
            overflow: hidden;
            position: relative;
        }

        .bar-fill {
            height: 100%;
            border-radius: 4px;
