        }

        .bar-openai { background: linear-gradient(90deg, var(--openai), rgba(16, 163, 127, 0.7)); }
        .bar-google { background: linear-gradient(90deg, var(--google), rgba(66, 133, 244, 0.7)); }
        .bar-anthropic { background: linear-gradient(90deg, var(--anthropic), rgba(212, 165, 116, 0.7)); }
        .bar-muse { background: linear-gradient(90deg, var(--muse), rgba(168, 85, 247, 0.7)); }

        /* ===========================================
           COMPARISON BARS (Side by side)
           =========================================== */
        .comparison-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .comparison-panel {
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(0.8rem, 2vw, 1.5rem);
        }

        .comparison-panel h3 {
            font-size: clamp(0.9rem, 1.5vw, 1.2rem);
            margin-bottom: var(--element-gap);
            color: var(--text-primary);
        }

        /* ===========================================
           HEATMAP MATRIX
           =========================================== */
        .heatmap-matrix {
            display: grid;
            grid-template-columns: 1.5fr repeat(4, 1fr);
            gap: 2px;
            margin-top: var(--content-gap);
            font-size: var(--small-size);
        }

        .heatmap-header {
            background: var(--bg-card);
            padding: clamp(0.4rem, 1vw, 0.8rem);
            font-weight: 700;
            text-align: center;
            color: var(--accent);
        }

        .heatmap-cell {
            background: var(--bg-card);
            padding: clamp(0.3rem, 0.8vw, 0.6rem);
            text-align: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            border-radius: 4px;
            min-height: clamp(40px, 6vw, 70px);
        }

        .heatmap-cell .lab-name {
            font-weight: 700;
            font-size: clamp(0.6rem, 1vw, 0.85rem);
        }

        .heatmap-cell .benchmark-name {
            font-size: clamp(0.5rem, 0.8vw, 0.7rem);
            color: var(--text-secondary);
            margin-top: 2px;
        }

        .cell-openai { background: rgba(16, 163, 127, 0.3); }
        .cell-google { background: rgba(66, 133, 244, 0.3); }
        .cell-anthropic { background: rgba(212, 165, 116, 0.3); }
        .cell-muse { background: rgba(168, 85, 247, 0.3); }

        /* ===========================================
           CONTRAST VISUALIZATION (Safety slide)
           =========================================== */
        .contrast-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .contrast-panel {
            background: var(--bg-card);
            border-radius: 12px;
            padding: clamp(1rem, 2vw, 2rem);
            text-align: center;
        }

        .contrast-panel.highlight {
            border: 2px solid var(--accent);
            box-shadow: 0 0 30px rgba(0, 255, 204, 0.2);
        }

        .contrast-panel.lowlight {
            border: 2px solid var(--accent-secondary);
            box-shadow: 0 0 30px rgba(255, 0, 170, 0.1);
        }

        .contrast-value {
            font-family: var(--font-display);
            font-size: clamp(2rem, 5vw, 4rem);
            font-weight: 700;
            margin: var(--element-gap) 0;
        }

        .contrast-panel.highlight .contrast-value { color: var(--accent); }
        .contrast-panel.lowlight .contrast-value { color: var(--accent-secondary); }

        .contrast-label {
            font-size: var(--h3-size);
            font-weight: 600;
            margin-bottom: var(--element-gap);
        }

        .contrast-desc {
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           TAKEAWAYS LIST
           =========================================== */
        .takeaways {
            display: flex;
            flex-direction: column;
            gap: var(--content-gap);
            margin-top: var(--content-gap);
        }

        .takeaway-item {
            display: flex;
            gap: var(--element-gap);
            align-items: flex-start;
            background: var(--bg-card);
            padding: clamp(0.8rem, 2vw, 1.5rem);
            border-radius: 8px;
            border-left: 3px solid var(--accent);
        }

        .takeaway-item.muse-accent { border-left-color: var(--muse); }

        .takeaway-number {
            font-family: var(--font-display);
            font-size: clamp(1.2rem, 2.5vw, 2rem);
            font-weight: 700;
            color: var(--accent);
            line-height: 1;
        }

        .takeaway-item.muse-accent .takeaway-number { color: var(--muse); }

        .takeaway-text {
            font-size: var(--body-size);
            color: var(--text-primary);
        }

        /* ===========================================
           NAVIGATION
           =========================================== */
        .nav-dots {
            position: fixed;
            right: clamp(1rem, 2vw, 2rem);
            top: 50%;
            transform: translateY(-50%);
            display: flex;
            flex-direction: column;
            gap: 8px;
            z-index: 100;
        }

        .nav-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.2);
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .nav-dot.active {
            background: var(--accent);
            box-shadow: 0 0 10px var(--accent-glow);
        }

        .nav-dot:hover {
            background: rgba(255, 255, 255, 0.5);
        }

        /* ===========================================
           PROGRESS BAR
           =========================================== */
        .progress-bar {
            position: fixed;
            top: 0;
            left: 0;
            height: 3px;
            background: var(--accent);
            z-index: 100;
            transition: width 0.3s ease;
        }

        /* ===========================================
           SLIDE NUMBER
           =========================================== */
        .slide-number {
            position: absolute;
            bottom: var(--slide-padding);
            right: var(--slide-padding);
            font-size: var(--small-size);
            color: var(--text-secondary);
        }

        /* ===========================================
           TITLE SLIDE SPECIFIC
           =========================================== */
        .title-slide {
            justify-content: center;
            align-items: center;
            text-align: center;
        }

        .title-slide h1 {
            max-width: 90vw;
        }

        .subtitle {
            font-size: var(--h3-size);
            color: var(--text-secondary);
            margin-top: var(--content-gap);
        }

        .stats-row {
            display: flex;
            gap: clamp(1.5rem, 4vw, 4rem);
            margin-top: var(--content-gap);
            justify-content: center;
        }

        .stat-item {
